package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdGenerators;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.BeanDeserializerBuilder;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDelegatingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.exc.IgnoredPropertyException;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.BeanPropertyMap;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.util.*;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_createContextual_TriageGen1Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private AnnotationIntrospector intr;
    private BeanDeserializerBuilder builder;
    private BeanDescription beanDesc;
    private BeanPropertyMap beanProperties;
    private Class<?> handledType;

    // Concrete implementation of the abstract class for testing
    public static class TestBeanDeserializer extends BeanDeserializer {
        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties, Map<String, SettableBeanProperty> backRefs, Set<String> ignorableProps, boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(NameTransformer unwrapper) { return this; }

        @Override
        protected BeanDeserializer asArrayDeserializer() {
            return new TestBeanDeserializer(this);
        }
    }

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        intr = mock(AnnotationIntrospector.class);
        builder = mock(BeanDeserializerBuilder.class);
        beanDesc = mock(BeanDescription.class);
        beanProperties = mock(BeanPropertyMap.class);
        handledType = String.class;

        when(ctxt.getAnnotationIntrospector()).thenReturn(intr);
        when(ctxt.getTypeFactory()).thenReturn(com.fasterxml.jackson.databind.type.TypeFactory.defaultInstance());

        // Setup basic structure for the deserializer
        TestBeanDeserializer deserializer = new TestBeanDeserializer(
                builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false);

        // Mock handledType via reflection or by ensuring the builder/desc provides it
        // Since we can't easily mock handledType() as it's a final method in some versions or intrinsic, 
        // we rely on the implementation logic.
    }

    @Test
    public void testCreateContextual_NullPropertyAndIntrospector() throws JsonMappingException {
        TestBeanDeserializer deserializer = new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false);
        JsonDeserializer<?> result = deserializer.createContextual(ctxt, null);
        assertEquals(deserializer, result);
    }

    @Test
    public void testCreateContextual_NoObjectIdInfo() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        TestBeanDeserializer deserializer = new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false);
        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertEquals(deserializer, result);
    }

    @Test
    public void testCreateContextual_PropertyBasedObjectIdSuccess() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("id");
        when(objectIdInfo.getScope()).thenReturn("scope");

        SettableBeanProperty idProp = mock(SettableBeanProperty.class);
        when(idProp.getType()).thenReturn(ctxt.getTypeFactory().constructType(String.class));

        // Mock findProperty via a spy or actual implementation if possible. 
        // Since findProperty is a method of BeanDeserializer, we use a spy.
        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false));
        doReturn(idProp).when(deserializer).findProperty("id");
        doReturn(String.class).when(deserializer).handledType();

        when(ctxt.objectIdResolverInstance(any(), any())).thenReturn(mock(ObjectIdResolver.class));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertNotNull(result);
        verify(deserializer).withObjectIdReader(any(ObjectIdReader.class));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateContextual_PropertyBasedObjectIdFailure() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.PropertyGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("missingId");

        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false));
        doReturn(null).when(deserializer).findProperty("missingId");
        doReturn(String.class).when(deserializer).handledType();

        deserializer.createContextual(ctxt, property);
    }

    @Test
    public void testCreateContextual_OtherObjectIdGenerator() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);

        ObjectIdInfo objectIdInfo = mock(ObjectIdInfo.class);
        when(intr.findObjectIdInfo(member)).thenReturn(objectIdInfo);
        when(intr.findObjectReferenceInfo(eq(member), any())).thenReturn(objectIdInfo);
        when(objectIdInfo.getGeneratorType()).thenReturn(ObjectIdGenerators.UUIDGenerator.class);
        when(objectIdInfo.getPropertyName()).thenReturn("id");

        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false));

        when(ctxt.constructType(any())).thenReturn(ctxt.getTypeFactory().constructType(String.class));
        when(ctxt.objectIdGeneratorInstance(any(), any())).thenReturn(mock(ObjectIdGenerator.class));
        when(ctxt.findRootValueDeserializer(any())).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_WithIgnorableProperties() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);

        JsonIgnoreProperties.Value ignorals = mock(JsonIgnoreProperties.Value.class);
        when(intr.findPropertyIgnorals(member)).thenReturn(ignorals);
        when(ignorals.findIgnoredForDeserialization()).thenReturn(new HashSet<>(Collections.singletonList("prop1")));

        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(Collections.singletonList("prop0")), true, false));

        deserializer.createContextual(ctxt, property);

        // Verify that it attempts to merge "prop1" and "prop0"
        verify(deserializer).withIgnorableProperties(argThat(set -> set.contains("prop0") && set.contains("prop1")));
    }

    @Test
    public void testCreateContextual_JsonFormatCaseInsensitivity() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);
        when(intr.findPropertyIgnorals(member)).thenReturn(null);

        // Mock format override
        JsonFormat.Value format = JsonFormat.forFormat(JsonFormat.Shape.OBJECT); 
        // We need to simulate the feature being present
        // Since JsonFormat.Value is hard to mock, we use a real one if possible or mock it
        JsonFormat.Value mockedFormat = mock(JsonFormat.Value.class);
        when(mockedFormat.hasShape()).thenReturn(true);
        when(mockedFormat.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(mockedFormat.getFeature(JsonFormat.Feature.ACCEPT_CASE_INSENSITIVE_PROPERTIES)).thenReturn(true);

        // We need to mock findFormatOverrides which is a protected method
        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false));
        doReturn(mockedFormat).when(deserializer).findFormatOverrides(any(), any(), any());

        // Mock BeanPropertyMap behavior
        BeanPropertyMap caseInsensitiveProps = mock(BeanPropertyMap.class);
        when(beanProperties.withCaseInsensitivity(true)).thenReturn(caseInsensitiveProps);

        deserializer.createContextual(ctxt, property);
        verify(deserializer).withBeanProperties(caseInsensitiveProps);
    }

    @Test
    public void testCreateContextual_AsArrayDeserializer() throws JsonMappingException {
        AnnotatedMember member = mock(AnnotatedMember.class);
        when(property.getMember()).thenReturn(member);
        when(intr.findObjectIdInfo(member)).thenReturn(null);
        when(intr.findPropertyIgnorals(member)).thenReturn(null);

        JsonFormat.Value mockedFormat = mock(JsonFormat.Value.class);
        when(mockedFormat.hasShape()).thenReturn(true);
        when(mockedFormat.getShape()).thenReturn(JsonFormat.Shape.ARRAY);

        TestBeanDeserializer deserializer = spy(new TestBeanDeserializer(builder, beanDesc, beanProperties, new HashMap<>(), new HashSet<>(), true, false));
        doReturn(mockedFormat).when(deserializer).findFormatOverrides(any(), any(), any());

        deserializer.createContextual(ctxt, property);
        verify(deserializer).asArrayDeserializer();
    }
}
